function chooseMusic(){const preference=window.AlpinePro?.settings?.music||'random',germanRoute=routeIndex>=5&&routeIndex<=7,ids=germanRoute?['tiroler']:['copperhead','highway','roadhouse','roadkill'],id=preference==='random'?ids[Math.floor(Math.random()*ids.length)]:MUSIC_TRACKS[preference]?preference:'copperhead';if(id===activeMusicId&&music.src)return;activeMusicId=id;music.src=MUSIC_TRACKS[id].src;music.setAttribute('aria-label',MUSIC_TRACKS[id].label);music.load()}
