const drawWeatherLayer=draw;draw=function(){drawWeatherLayer();if(state!=='playing'||snowSurface()!=='WHITEOUT')return;ctx.save();const veil=ctx.createLinearGradient(0,0,0,H);veil.addColorStop(0,'rgba(232,248,255,.08)');veil.addColorStop(.48,'rgba(236,249,255,.2)');veil.addColorStop(1,'rgba(236,249,255,.42)');ctx.fillStyle=veil;ctx.fillRect(0,0,W,H);ctx.fillStyle='rgba(255,255,255,.75)';ctx.font='800 9px DM Sans';ctx.textAlign='center';ctx.fillText('WHITEOUT · FIND THE FALL LINE',W*.5,H*.2);ctx.restore()};
const updateUIFrame=updateUI;let uiPaintAt=0;updateUI=function(){const now=performance.now();if(state==='playing'&&now-uiPaintAt<80)return;uiPaintAt=now;updateUIFrame()};
const patrolSpawn=spawn;spawn=function(){const before=obstacles.length;patrolSpawn();for(let i=before;i<obstacles.length;i++){const o=obstacles[i];if(o.type==='speedPatrol')o.laneV=(Math.random()>.5?1:-1)*(.07+Math.random()*.035);if(o.type==='skiPatrol')o.laneV=(Math.random()>.5?1:-1)*(.018+Math.random()*.012)}};
const patrolUpdate=update;update=function(dt){patrolUpdate(dt);if(state!=='playing')return;obstacles.forEach(o=>{if(!['speedPatrol','skiPatrol'].includes(o.type))return;o.x+=o.laneV*dt*speed;if(o.x<.1||o.x>.9){o.x=Math.max(.1,Math.min(.9,o.x));o.laneV*=-1}})};
const patrolDraw=drawObstacle;drawObstacle=function(o){if(!['speedPatrol','skiPatrol'].includes(o.type)){patrolDraw(o);return}if(o.y<.4)return;const t=Math.max(0,Math.min(1,(o.y-.4)/.48)),scale=.22+t*.9;ctx.save();ctx.translate(o.x*W,o.y*H);ctx.scale(scale,scale);ctx.fillStyle=o.type==='speedPatrol'?'#e84d3d':'#2e8f9f';ctx.fillRect(-17,-31,34,8);ctx.fillStyle='#fff';ctx.font='900 7px DM Sans';ctx.textAlign='center';ctx.fillText(o.type==='speedPatrol'?'SPEED PATROL':'SKI PATROL',0,-25);drawSkier(0,0,Math.sin(o.wobble+o.y*9)*.16,o.type==='speedPatrol'?'#e84d3d':'#2e8f9f',false);ctx.restore()};
const drawDesignBase=drawRiderDetails;drawRiderDetails=function(){drawDesignBase();ctx.save();ctx.strokeStyle=GOGGLES[goggleIndex]||GOGGLES[0];ctx.lineWidth=2.8;ctx.beginPath();ctx.moveTo(-7,-22);ctx.lineTo(7,-22);ctx.stroke();ctx.strokeStyle=SKINS[skinIndex].b;ctx.lineWidth=2;if(styleIndex===1){ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(9,9);ctx.stroke()}else if(styleIndex===2){ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(0,12);ctx.stroke();ctx.strokeStyle='rgba(255,255,255,.65)';ctx.beginPath();ctx.moveTo(-8,0);ctx.lineTo(8,0);ctx.stroke()}ctx.restore()};
const shortcutHit=hitObstacle;hitObstacle=function(o,dx){if(o.type==='shortcut'){o.cleared=true;const points=650*combo;score+=points;speed=Math.min(3.9,speed+.55);combo=Math.min(8,combo+2);comboTime=3.8;bestCombo=Math.max(bestCombo,combo);scorePop(points,o.x*W,o.y*H,'SHORTCUT SEND');toast('SECRET LINE',`+${points}`);burst(o.x*W,o.y*H,'#ffd260',30);beep(1040,.2);return}if(o.type==='patch'){o.cleared=true;const points=900*combo;score+=points;combo=Math.min(8,combo+1);comboTime=4.2;bestCombo=Math.max(bestCombo,combo);scorePop(points,o.x*W,o.y*H,'PATCH FOUND');toast('MOUNTAIN PATCH',`+${points}`);burst(o.x*W,o.y*H,'#69e1f5',34);beep(1180,.22);return}shortcutHit(o,dx)};
const shortcutClear=clearObstacle;clearObstacle=function(o,dx){if(o.type==='shortcut'||o.type==='patch'){return hitObstacle(o,dx)}shortcutClear(o,dx)};
const shortcutDraw=drawObstacle;drawObstacle=function(o){if(o.type!=='shortcut'&&o.type!=='patch'){shortcutDraw(o);return}if(o.y<.4)return;const t=Math.max(0,Math.min(1,(o.y-.4)/.48)),scale=.22+t*.9;ctx.save();ctx.translate(o.x*W,o.y*H);ctx.scale(scale,scale);if(o.type==='shortcut'){ctx.strokeStyle='#ffd260';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-27,22);ctx.lineTo(-27,-24);ctx.quadraticCurveTo(0,-45,27,-24);ctx.lineTo(27,22);ctx.stroke();ctx.fillStyle='#142832';ctx.fillRect(-23,-17,46,13);ctx.fillStyle='#ffd260';ctx.font='900 7px DM Sans';ctx.textAlign='center';ctx.fillText('SHORTCUT',0,-8)}else{ctx.fillStyle='#69e1f5';ctx.beginPath();ctx.arc(0,0,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='#102a38';ctx.font='900 10px DM Sans';ctx.textAlign='center';ctx.fillText('PATCH',0,4);ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke()}ctx.restore()};
